import math
from collections import defaultdict
from typing import Dict, List, Set, Tuple

def two_adic_decomp(m):
    if m == 0: return (0, 0)
    s, d = 0, m
    while d % 2 == 0: s += 1; d //= 2
    return (s, d)

def is_strong_liar(n, a):
    if n <= 2 or a <= 0: return False
    if math.gcd(a, n) != 1: return False
    s, d = two_adic_decomp(n - 1)
    x = pow(a, d, n)
    if x == 1 or x == n - 1: return True
    for _ in range(s - 1):
        x = pow(x, 2, n)
        if x == n - 1: return True
        if x == 1: return False
    return False

def strong_liar_set(n):
    if n <= 3: return set()
    return {a for a in range(2, n) if math.gcd(a, n) == 1 and is_strong_liar(n, a)}

def representation_count(S, n):
    r = defaultdict(int)
    for a in S:
        for b in S:
            r[(a + b) % n] += 1
    return dict(r)

def additive_energy(S, n):
    r = representation_count(S, n)
    return sum(v * v for v in r.values())

def additive_energy_exponent(S, n):
    if len(S) <= 1: return 0.0
    E = additive_energy(S, n)
    return math.log(E) / math.log(len(S)) if E > 0 else 0.0

def crt_fiber(S, n, p):
    return {a % p for a in S}

# --- Application: Energy fingerprinting ---
